const error = $input.first().json;

const workflowName = error.workflow?.name || 'Unknown Workflow';
const executionId = error.execution?.id || 'Unknown';
const errorMessage = error.error?.message || 'No error message available';
const errorNode = error.node?.name || 'Unknown node';
const errorTime = error.execution?.startedAt || new Date().toISOString();

const subject = `❌ n8n Workflow Failed: ${workflowName}`;

const message = `Workflow Execution Failed!

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Workflow: ${workflowName}
Execution ID: ${executionId}
Failed At: ${errorTime}
Failed Node: ${errorNode}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

Error Details:
${errorMessage}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

Stack Trace:
${error.error?.stack || 'Not available'}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

Please check n8n for full execution details:
${error.execution?.url || 'URL not available'}
`;

return [{
  json: {
    subject,
    message,
    workflowName,
    executionId,
    errorNode,
    errorMessage
  }
}];
